// Pruebas de REQ-004 — encabezado del informe mensual (src/formato.js).
// Viven fuera de `src/` a propósito: `codigo_app.globs` del manifiesto es `src/*`,
// y el `qa-tester` debe poder editarlas.
const test = require('node:test');
const assert = require('node:assert/strict');

const { listaClientes, tituloInforme } = require('../src/formato.js');

test('CA-01 — dos o más nombres se unen con "; ", en orden y sin separador en los extremos', () => {
  assert.equal(listaClientes(['Ana', 'Beto']), 'Ana; Beto');
  assert.equal(
    listaClientes(['Ana', 'Beto', 'Carla']),
    'Ana; Beto; Carla',
    'orden de recepción y separador «punto y coma + espacio»',
  );
});

test('CA-01 — el resultado no empieza ni termina con el separador', () => {
  const resultado = listaClientes(['Ana', 'Beto']);
  assert.ok(!resultado.startsWith(';'), 'no hay separador delante del primero');
  assert.ok(!resultado.endsWith(';') && !resultado.endsWith('; '), 'no hay separador detrás del último');
});

test('CA-02 — se omite todo elemento que el predicado trata como «no aporta nombre» (falsy)', () => {
  assert.equal(listaClientes(['Ana', '', 'Beto']), 'Ana; Beto');
  assert.equal(listaClientes(['Ana', null, undefined, 'Beto']), 'Ana; Beto');
  // La propiedad contratada es «valor falsy», no una lista cerrada de casos.
  assert.equal(listaClientes(['Ana', 0, false, NaN, 'Beto']), 'Ana; Beto');
});

test('CA-02 — un nombre conservado se copia tal cual, sin recorte de espacios', () => {
  assert.equal(listaClientes(['Ana', '   ', 'Beto']), 'Ana;    ; Beto');
  assert.equal(listaClientes([' Ana ']), ' Ana ');
});

test('CA-03 — el título va íntegro en minúsculas, incluida la inicial de «informe» y la del mes', () => {
  assert.equal(tituloInforme(9, 2026), 'informe de septiembre de 2026');
  assert.equal(tituloInforme(1, 2026), 'informe de enero de 2026');
  assert.equal(tituloInforme(12, 2025), 'informe de diciembre de 2025');
});

test('CA-03 — ningún ordinal de 1 a 12 produce una letra mayúscula', () => {
  for (let mes = 1; mes <= 12; mes += 1) {
    const titulo = tituloInforme(mes, 2026);
    assert.equal(titulo, titulo.toLowerCase(), `mes ${mes}: ${titulo}`);
    assert.ok(titulo.startsWith('informe de '), `mes ${mes}: ${titulo}`);
    assert.ok(titulo.endsWith(' de 2026'), `mes ${mes}: ${titulo}`);
  }
});

test('CA-04 — sin ningún nombre conservado devuelve la cadena vacía', () => {
  assert.equal(listaClientes([]), '');
  assert.equal(listaClientes(['', null, undefined]), '');
});

test('CA-05 — un solo nombre conservado sale solo, sin separador', () => {
  assert.equal(listaClientes(['Ana']), 'Ana');
  assert.equal(listaClientes([null, 'Ana', '']), 'Ana');
});

